<?php
declare(strict_types=1);
session_start();
require __DIR__ . '/config.php';

if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32));
$notice = $_SESSION['notice'] ?? null;
unset($_SESSION['notice']);
$active = $_GET['aba'] ?? 'visao-geral';
$allowed = ['visao-geral', 'produtos', 'clientes', 'vendas', 'relatorios'];
if (!in_array($active, $allowed, true)) $active = 'visao-geral';
$error = null;

try {
    $pdo = db();
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        if (!hash_equals($_SESSION['csrf'], (string)($_POST['csrf'] ?? ''))) throw new RuntimeException('Sessão expirada. Atualize a página e tente novamente.');
        $action = $_POST['action'] ?? '';
        if ($action === 'product') {
            $id = (int)($_POST['id'] ?? 0);
            $name = trim((string)($_POST['name'] ?? ''));
            $sku = trim((string)($_POST['sku'] ?? ''));
            $category = trim((string)($_POST['category'] ?? 'Geral')) ?: 'Geral';
            $price = filter_var($_POST['price'] ?? null, FILTER_VALIDATE_FLOAT);
            $stock = filter_var($_POST['stock'] ?? null, FILTER_VALIDATE_INT);
            $min = filter_var($_POST['min_stock'] ?? null, FILTER_VALIDATE_INT);
            if ($name === '' || $sku === '' || $price === false || $price < 0 || $stock === false || $stock < 0 || $min === false || $min < 0) throw new RuntimeException('Preencha os dados do produto com valores válidos.');
            if ($id) $stmt = $pdo->prepare('UPDATE products SET name=?, sku=?, category=?, price=?, stock=?, min_stock=? WHERE id=?');
            else $stmt = $pdo->prepare('INSERT INTO products (name,sku,category,price,stock,min_stock) VALUES (?,?,?,?,?,?)');
            $values = [$name,$sku,$category,$price,$stock,$min]; if ($id) $values[] = $id;
            $stmt->execute($values); $_SESSION['notice'] = 'Produto salvo com sucesso.'; header('Location: ?aba=produtos'); exit;
        }
        if ($action === 'customer') {
            $name = trim((string)($_POST['name'] ?? '')); $email = trim((string)($_POST['email'] ?? '')); $phone = trim((string)($_POST['phone'] ?? ''));
            if ($name === '') throw new RuntimeException('Informe o nome do cliente.');
            if ($email !== '' && !filter_var($email, FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Informe um e-mail válido.');
            $stmt = $pdo->prepare('INSERT INTO customers (name,email,phone) VALUES (?,?,?)'); $stmt->execute([$name,$email ?: null,$phone ?: null]);
            $_SESSION['notice'] = 'Cliente cadastrado com sucesso.'; header('Location: ?aba=clientes'); exit;
        }
        if ($action === 'delete_product') {
            $stmt = $pdo->prepare('DELETE FROM products WHERE id=?'); $stmt->execute([(int)($_POST['id'] ?? 0)]);
            $_SESSION['notice'] = 'Produto removido.'; header('Location: ?aba=produtos'); exit;
        }
        if ($action === 'sale') {
            $customer = (int)($_POST['customer_id'] ?? 0) ?: null;
            $ids = $_POST['product_id'] ?? []; $qtys = $_POST['quantity'] ?? [];
            if (!is_array($ids) || !is_array($qtys) || count($ids) !== count($qtys)) throw new RuntimeException('Itens da venda inválidos.');
            $items = []; foreach ($ids as $i => $rawId) { $pid=(int)$rawId; $qty=filter_var($qtys[$i] ?? null,FILTER_VALIDATE_INT); if ($pid > 0 && $qty !== false && $qty > 0) $items[$pid]=($items[$pid] ?? 0)+$qty; }
            if (!$items) throw new RuntimeException('Adicione pelo menos um produto à venda.');
            $pdo->beginTransaction(); $lines=[]; $total=0.0;
            $lock=$pdo->prepare('SELECT id,name,price,stock FROM products WHERE id=? FOR UPDATE');
            foreach ($items as $pid=>$qty) { $lock->execute([$pid]); $p=$lock->fetch(); if (!$p) throw new RuntimeException('Um produto selecionado não existe.'); if ((int)$p['stock'] < $qty) throw new RuntimeException('Estoque insuficiente para ' . $p['name'] . '. Disponível: ' . $p['stock'] . '.'); $lines[]=['id'=>$pid,'qty'=>$qty,'price'=>(float)$p['price']]; $total += (float)$p['price']*$qty; }
            $stmt=$pdo->prepare('INSERT INTO sales (customer_id,total) VALUES (?,?)'); $stmt->execute([$customer,$total]); $saleId=(int)$pdo->lastInsertId();
            $lineStmt=$pdo->prepare('INSERT INTO sale_items (sale_id,product_id,quantity,unit_price) VALUES (?,?,?,?)'); $stockStmt=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');
            foreach ($lines as $line) { $lineStmt->execute([$saleId,$line['id'],$line['qty'],$line['price']]); $stockStmt->execute([$line['qty'],$line['id']]); }
            $pdo->commit(); $_SESSION['notice']='Venda #'.$saleId.' registrada. Total: '.money($total); header('Location: ?aba=vendas'); exit;
        }
    }
    $stats = [
        'sales_today' => (float)$pdo->query('SELECT COALESCE(SUM(total),0) FROM sales WHERE DATE(created_at)=CURDATE()')->fetchColumn(),
        'orders_today' => (int)$pdo->query('SELECT COUNT(*) FROM sales WHERE DATE(created_at)=CURDATE()')->fetchColumn(),
        'products' => (int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),
        'low_stock' => (int)$pdo->query('SELECT COUNT(*) FROM products WHERE stock<=min_stock')->fetchColumn(),
    ];
    $products=$pdo->query('SELECT * FROM products ORDER BY name')->fetchAll();
    $customers=$pdo->query('SELECT * FROM customers ORDER BY name')->fetchAll();
    $recent=$pdo->query('SELECT s.id,s.total,s.created_at,c.name customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id ORDER BY s.created_at DESC LIMIT 8')->fetchAll();
    $lowProducts=$pdo->query('SELECT * FROM products WHERE stock<=min_stock ORDER BY stock ASC LIMIT 6')->fetchAll();
    $report=$pdo->query("SELECT DATE(created_at) day, COUNT(*) orders, SUM(total) total FROM sales WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 6 DAY) GROUP BY DATE(created_at) ORDER BY day")->fetchAll();
    $topProducts=$pdo->query('SELECT p.name,SUM(i.quantity) quantity,SUM(i.quantity*i.unit_price) revenue FROM sale_items i JOIN products p ON p.id=i.product_id GROUP BY p.id,p.name ORDER BY quantity DESC LIMIT 5')->fetchAll();
    $reportTotals = [
        'revenue' => (float)$pdo->query('SELECT COALESCE(SUM(total),0) FROM sales')->fetchColumn(),
        'count' => (int)$pdo->query('SELECT COUNT(*) FROM sales')->fetchColumn(),
        'average' => (float)$pdo->query('SELECT COALESCE(AVG(total),0) FROM sales')->fetchColumn(),
        'stock_value' => (float)$pdo->query('SELECT COALESCE(SUM(stock*price),0) FROM products')->fetchColumn(),
    ];
} catch (Throwable $e) {
    if (isset($pdo) && $pdo->inTransaction()) $pdo->rollBack();
    $error = $e instanceof PDOException ? ($e->getCode() === '23000' ? 'Este produto já aparece em vendas e não pode ser removido.' : 'Não foi possível conectar ao banco. Importe schema.sql e confira as credenciais em config.php.') : $e->getMessage();
    $stats=['sales_today'=>0,'orders_today'=>0,'products'=>0,'low_stock'=>0]; $products=$customers=$recent=$lowProducts=$report=$topProducts=[];
    $reportTotals=['revenue'=>0,'count'=>0,'average'=>0,'stock_value'=>0];
}
$titles=['visao-geral'=>'Visão geral','produtos'=>'Produtos','clientes'=>'Clientes','vendas'=>'Vendas','relatorios'=>'Relatórios'];
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= h($titles[$active]) ?> · Prime</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="style.css"></head><body>
