<?php if($notice): ?><div class="alert success"><?= h($notice) ?><button class="close-alert">×</button></div><?php endif ?><?php if($error): ?><div class="alert error"><b>Banco de dados indisponível</b><br><?= h($error) ?> <span>— consulte o arquivo README.md para iniciar.</span></div><?php endif ?>
<?php if($active==='visao-geral'): ?><section class="stat-grid"><article class="stat-card"><div class="stat-top"><span>Vendas hoje</span><span class="stat-icon green">↗</span></div><strong><?= money($stats['sales_today']) ?></strong><small>Faturamento do dia</small></article><article class="stat-card"><div class="stat-top"><span>Pedidos hoje</span><span class="stat-icon blue">▤</span></div><strong><?= $stats['orders_today'] ?></strong><small>Vendas registradas</small></article><article class="stat-card"><div class="stat-top"><span>Produtos ativos</span><span class="stat-icon purple">▦</span></div><strong><?= $stats['products'] ?></strong><small>Itens no catálogo</small></article><article class="stat-card"><div class="stat-top"><span>Estoque baixo</span><span class="stat-icon orange">⚑</span></div><strong><?= $stats['low_stock'] ?></strong><small>Itens no ponto de reposição</small></article></section><section class="dashboard-grid"><article class="panel chart-panel"><div class="panel-head"><div><h2>Desempenho de vendas</h2><p>Faturamento nos últimos 7 dias</p></div><span class="tag">Últimos 7 dias⌄</span></div><div class="chart" id="sales-chart" data-values="<?= h(json_encode(array_map(fn($r)=>(float)$r['total'],$report))) ?>" data-labels="<?= h(json_encode(array_map(fn($r)=>date('d/m',strtotime($r['day'])),$report))) ?>"><div class="chart-y"><span>R$ 4k</span><span>R$ 3k</span><span>R$ 2k</span><span>R$ 1k</span><span>R$ 0</span></div><div class="chart-area"><div class="gridlines"><i></i><i></i><i></i><i></i><i></i></div><svg viewBox="0 0 700 190" preserveAspectRatio="none" aria-label="Gráfico de vendas dos últimos sete dias"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#1d8a68" stop-opacity=".22"/><stop offset="1" stop-color="#1d8a68" stop-opacity="0"/></linearGradient></defs><path class="chart-fill"/><path class="chart-line"/><g class="chart-dots"></g></svg><div class="chart-x"></div></div></div></article><article class="panel"><div class="panel-head"><div><h2>Estoque em atenção</h2><p>Produtos no limite mínimo</p></div><a class="text-link" href="?aba=produtos">Ver todos ↗</a></div><div class="stock-list"><?php if(!$lowProducts): ?><div class="empty">Tudo certo! Nenhum item precisa de reposição.</div><?php else: foreach($lowProducts as $p): ?><div class="stock-row"><div class="product-thumb">▦</div><div class="stock-name"><b><?= h($p['name']) ?></b><small><?= h($p['sku']) ?></small></div><span class="stock-count <?= (int)$p['stock']===0?'out':'' ?>"><?= (int)$p['stock'] ?> un.<small>Mín. <?= (int)$p['min_stock'] ?></small></span></div><?php endforeach; endif ?></div></article></section><section class="panel table-panel"><div class="panel-head"><div><h2>Vendas recentes</h2><p>Últimas movimentações da loja</p></div><a class="text-link" href="?aba=vendas">Ver todas ↗</a></div><?php renderSales($recent); ?></section>
<?php elseif($active==='produtos'): ?><section class="panel table-panel"><div class="table-toolbar"><div class="search-box"><span>⌕</span><input class="table-search" placeholder="Buscar produto ou SKU..."></div><span class="result-count"><?= count($products) ?> produtos</span></div><div class="table-wrap"><table><thead><tr><th>PRODUTO</th><th>CATEGORIA</th><th>PREÇO</th><th>ESTOQUE</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($products as $p): ?><tr data-search="<?= h(strtolower($p['name'].' '.$p['sku'].' '.$p['category'])) ?>"><td><div class="cell-product"><div class="product-thumb">▦</div><div><b><?= h($p['name']) ?></b><small><?= h($p['sku']) ?></small></div></div></td><td><?= h($p['category']) ?></td><td class="strong"><?= money($p['price']) ?></td><td><?= (int)$p['stock'] ?> un.</td><td><span class="badge <?= (int)$p['stock']<=(int)$p['min_stock']?'warning':'ok' ?>"><i></i><?= (int)$p['stock']<=(int)$p['min_stock']?'Estoque baixo':'Disponível' ?></span></td><td><button class="row-menu" title="Remover" data-delete="<?= (int)$p['id'] ?>">···</button></td></tr><?php endforeach; if(!$products): ?><tr><td colspan="6" class="empty">Nenhum produto cadastrado. Adicione o primeiro produto para começar.</td></tr><?php endif ?></tbody></table></div></section>
<?php elseif($active==='clientes'): ?><section class="panel table-panel"><div class="table-toolbar"><div class="search-box"><span>⌕</span><input class="table-search" placeholder="Buscar cliente..."></div><span class="result-count"><?= count($customers) ?> clientes</span></div><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>E-MAIL</th><th>TELEFONE</th><th>CADASTRADO EM</th></tr></thead><tbody><?php foreach($customers as $c): ?><tr data-search="<?= h(strtolower($c['name'].' '.$c['email'].' '.$c['phone'])) ?>"><td><div class="cell-product"><div class="avatar customer-avatar"><?= h(strtoupper(substr($c['name'],0,1))) ?></div><b><?= h($c['name']) ?></b></div></td><td><?= h($c['email'] ?: '—') ?></td><td><?= h($c['phone'] ?: '—') ?></td><td><?= date('d/m/Y',strtotime($c['created_at'])) ?></td></tr><?php endforeach; if(!$customers): ?><tr><td colspan="4" class="empty">Nenhum cliente cadastrado até agora.</td></tr><?php endif ?></tbody></table></div></section>
<?php elseif($active==='vendas'): ?><section class="panel table-panel"><div class="table-toolbar"><div class="search-box"><span>⌕</span><input class="table-search" placeholder="Buscar venda ou cliente..."></div><span class="result-count"><?= count($recent) ?> vendas recentes</span></div><?php renderSales($recent); ?></section>
<?php elseif($active==='relatorios'): ?><section class="stat-grid report-stats"><article class="stat-card"><div class="stat-top"><span>Faturamento total</span><span class="stat-icon green">↗</span></div><strong><?= money((float)$pdo->query('SELECT COALESCE(SUM(total),0) FROM sales')->fetchColumn()) ?></strong><small>Desde o início</small></article><article class="stat-card"><div class="stat-top"><span>Total de vendas</span><span class="stat-icon blue">▤</span></div><strong><?= (int)$pdo->query('SELECT COUNT(*) FROM sales')->fetchColumn() ?></strong><small>Pedidos concluídos</small></article><article class="stat-card"><div class="stat-top"><span>Ticket médio</span><span class="stat-icon purple">◎</span></div><strong><?php $avg=(float)$pdo->query('SELECT COALESCE(AVG(total),0) FROM sales')->fetchColumn(); echo money($avg); ?></strong><small>Valor por pedido</small></article><article class="stat-card"><div class="stat-top"><span>Clientes</span><span class="stat-icon orange">♙</span></div><strong><?= count($customers) ?></strong><small>Na base de cadastro</small></article></section><section class="dashboard-grid report-grid"><article class="panel"><div class="panel-head"><div><h2>Produtos mais vendidos</h2><p>Itens com maior volume de vendas</p></div></div><div class="top-list"><?php foreach($topProducts as $i=>$p): ?><div class="top-row"><span class="rank">0<?= $i+1 ?></span><div class="top-product"><b><?= h($p['name']) ?></b><small><?= (int)$p['quantity'] ?> unidades vendidas</small></div><strong><?= money($p['revenue']) ?></strong></div><?php endforeach; if(!$topProducts): ?><div class="empty">As vendas aparecerão aqui após os primeiros pedidos.</div><?php endif ?></div></article><article class="panel"><div class="panel-head"><div><h2>Resumo de estoque</h2><p>Posição atual do catálogo</p></div></div><div class="summary-lines"><div><span>Produtos cadastrados</span><b><?= count($products) ?></b></div><div><span>Unidades em estoque</span><b><?= array_sum(array_column($products,'stock')) ?></b></div><div><span>Precisam de reposição</span><b class="orange-text"><?= $stats['low_stock'] ?></b></div><div><span>Valor em estoque</span><b><?= money(array_sum(array_map(fn($p)=>(int)$p['stock']*(float)$p['price'],$products))) ?></b></div></div></article></section><?php endif ?></div></main>
