<?php function renderSales(array $sales): void { ?><div class="table-wrap"><table><thead><tr><th>VENDA</th><th>CLIENTE</th><th>DATA</th><th>VALOR</th><th>STATUS</th></tr></thead><tbody><?php foreach($sales as $s): ?><tr data-search="<?= h(strtolower('#'.$s['id'].' '.($s['customer']??''))) ?>"><td class="strong">#<?= (int)$s['id'] ?></td><td><?= h($s['customer'] ?: 'Venda sem cliente') ?></td><td><?= date('d/m/Y · H:i',strtotime($s['created_at'])) ?></td><td class="strong"><?= money($s['total']) ?></td><td><span class="badge ok"><i></i>Concluída</span></td></tr><?php endforeach; if(!$sales): ?><tr><td colspan="5" class="empty">Nenhuma venda registrada ainda.</td></tr><?php endif ?></tbody></table></div><?php } ?>
